// @generated by:gauntlet run:godseye-local-hermes-chat
import { randomUUID } from "node:crypto";
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { isAbsolute, join, relative, resolve } from "node:path";
import { openStore, type Store } from "@godseye/store";
import { expect, it } from "vitest";
import { agentsFixture } from "./helpers/agents-fixture.js";

it("T-AC-744 physically reopens private conversation progress and unknown correlation without another model submission", async () => {
  const directory = await mkdtemp(join(tmpdir(), "godseye-chat-reopen-"));
  const owned = relative(resolve(tmpdir()), resolve(directory));
  if (!owned || owned.startsWith("..") || isAbsolute(owned))
    throw new Error("Unsafe chat fixture root");
  let store: Store | undefined;
  try {
    const f = await agentsFixture({ dataDir: directory });
    store = f.store;
    const profile = await f.create();
    const detail = await f.infrastructure.agents.chatCreate(
      f.freshOwner(),
      {
        profileId: profile.id,
        expectedRevision: profile.revision,
        title: "Durable private conversation",
      },
      randomUUID(),
    );
    f.provider.submitScript = async (request, context) => {
      await context?.onEvent?.({
        type: "text.delta",
        sequence: 0,
        providerRunId: `provider-${request.taskId}`,
        text: "Retained provisional text",
      });
      return { state: "unknown", providerRunId: `provider-${request.taskId}`, stopped: false };
    };
    f.provider.inspectScript = async (request) => ({
      state: "unknown",
      providerRunId: request.providerRunId,
      stopped: false,
    });
    await f.infrastructure.agents.chatSend(
      f.freshOwner(),
      detail.conversation.id,
      {
        input: "A private durable question",
        expectedRevision: detail.conversation.revision,
      },
      randomUUID(),
    );
    await f.work();
    const before = await f.infrastructure.agents.chatDetail(f.freshOwner(), detail.conversation.id);
    const events = await f.infrastructure.agents.chatEvents(
      f.freshOwner(),
      detail.conversation.id,
      0,
    );
    expect(before.turns[0]).toMatchObject({
      partialText: "Retained provisional text",
      task: { state: "unknown" },
    });
    await store.close();
    store = undefined;
    store = await openStore({ dataDir: directory });
    const reopened = f.build(store);
    expect(await reopened.agents.chatDetail(f.freshOwner(), detail.conversation.id)).toEqual(
      before,
    );
    expect(await reopened.agents.chatEvents(f.freshOwner(), detail.conversation.id, 0)).toEqual(
      events,
    );
    expect(
      await reopened.agents.chatEvents(f.freshOwner(), detail.conversation.id, events.cursor),
    ).toMatchObject({ reset: false, events: [] });
    const task = before.turns[0]?.task;
    if (!task) throw new Error("Expected a retained uncertain task");
    await reopened.agents.reconcile(f.freshOwner(), task.id, randomUUID());
    expect(f.provider.submissions).toHaveLength(1);
    expect(f.provider.inspections.at(-1)?.conversation?.id).toBe(detail.conversation.id);
    expect(
      (await reopened.agents.chatDetail(f.freshOwner(), detail.conversation.id)).turns[0]?.task
        .state,
    ).toBe("unknown");
  } finally {
    await store?.close();
    await rm(directory, { recursive: true, force: true });
  }
});
